import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../components/Sidebar";

function Dashboard() {
  const [stats, setStats] = useState(null);
  const [upcomingSessions, setUpcomingSessions] = useState([]);
  const [recentActivity, setRecentActivity] = useState([]);
  const [loading, setLoading] = useState(true);
  const [unitProgress, setUnitProgress] = useState([]);

  const user = JSON.parse(localStorage.getItem("user"));
  const navigate = useNavigate();

  useEffect(() => {
    if (!user) return;

    async function loadDashboard() {
      try {
        const res = await fetch(`http://localhost:8080/dashboard/${user.id}`);
        const data = await res.json();

        setStats(data.stats);
        setUpcomingSessions(data.upcomingSessions);
        setRecentActivity(data.recentActivity);
        setUnitProgress(data.unitProgress || []);
        setLoading(false);
      } catch (err) {
        console.error("Dashboard error:", err);
        setLoading(false);
      }
    }

    loadDashboard();
  }, [user]);

  if (!user) {
    return <h1 style={{ color: "white" }}>Please log in</h1>;
  }

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Welcome back, {user.firstName}</h1>
            <p className="dashboard-subtitle">
              Track your XP, coins, lessons, games, and tutoring sessions.
            </p>
          </div>

          <button
            className="start-learning-btn"
            onClick={() => (window.location.href = "/resources")}
          >
            Start Learning
          </button>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading...</p>
        ) : (
          <>
            {/* STATS */}
            <section className="dashboard-stats-grid">
              <div className="stat-card xp-card">
                <h3>XP</h3>
                <p className="stat-value">{stats.xp}</p>
              </div>

              <div className="stat-card coins-card">
                <h3>Coins</h3>
                <p className="stat-value">{stats.coins}</p>
              </div>

              <div className="stat-card streak-card">
                <h3>Streak</h3>
                <p className="stat-value">{stats.streak} days</p>
              </div>

              <div className="stat-card lessons-card">
                <h3>Lessons</h3>
                <p className="stat-value">
                  {stats.lessonsCompleted}/{stats.lessonsCompleted + stats.lessonsInProgress}
                </p>
              </div>

              <div className="stat-card games-card">
                <h3>Game Score</h3>
                <p className="stat-value">{stats.totalGameScore}</p>
              </div>
            </section>

            {/* LEARNING UNITS */}
            <section className="dashboard-panel learning-units-panel">
              <h2>Learning Units</h2>
              {unitProgress.length === 0 ? (
                <p className="empty-text">No active units. Click Start Learning to begin.</p>
              ) : (
                <div className="units-grid">
                  {unitProgress.map((unit) => {
                    const percent = Math.round((unit.completed_lessons / unit.total_lessons) * 100 || 0);
                    return (
                      <div key={unit.subscience_id} className="unit-card card">
                        <div className="unit-card-top">
                          <h3>{unit.subscience_name}</h3>
                          <p className="unit-subject">{unit.science_name}</p>
                        </div>

                        <div className="unit-progress">
                          <div className="unit-progress-bar">
                            <div className="unit-progress-fill" style={{ width: `${percent}%` }} />
                          </div>
                          <p className="unit-progress-text">{percent}% • {unit.completed_lessons}/{unit.total_lessons} lessons</p>
                        </div>

                        <div className="unit-actions">
                          <button
                            className="primary-btn"
                            onClick={() => navigate(`/subscience/${unit.subscience_id}`)}
                          >
                            Continue
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </section>
            {/* LOWER SECTION */}
            <section className="dashboard-lower">
              {/* RECENT ACTIVITY */}
              <div className="dashboard-panel">
                <h2>Recent Activity</h2>
                {recentActivity.length === 0 ? (
                  <p className="empty-text">No activity yet.</p>
                ) : (
                  <ul className="activity-list">
                    {recentActivity.map((item) => (
                      <li key={item.id} className="activity-item">
                        <div>
                          <p className="activity-type">{item.type}</p>
                          <p className="activity-desc">{item.description}</p>
                          <p className="activity-subject">{item.subject}</p>
                        </div>
                        <span className="activity-time">
                          {new Date(item.created_at).toLocaleString()}
                        </span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              {/* UPCOMING SESSIONS */}
              <div className="dashboard-panel">
                <h2>Upcoming Sessions</h2>
                {upcomingSessions.length === 0 ? (
                  <p className="empty-text">No upcoming sessions.</p>
                ) : (
                  <ul className="sessions-list">
                    {upcomingSessions.map((session) => (
                      <li key={session.id} className="session-item">
                        <div>
                          <p className="session-subject">{session.subject}</p>
                          <p className="session-tutor">Tutor: {session.tutorName}</p>
                        </div>
                        <span className="session-time">
                          {new Date(session.session_time).toLocaleString()}
                        </span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </section>
          </>
        )}
      </main>
    </div>
  );
}

export default Dashboard;
